import{_ as r,y as n,a,o as i,a2 as e,D as s}from"./chunks/framework.DCcmcJcL.js";const _=JSON.parse('{"title":"Bundle Product","description":"","frontmatter":{},"headers":[],"relativePath":"product-types/bundle-product.md","filePath":"product-types/bundle-product.md","lastUpdated":1789441803000}'),d={name:"product-types/bundle-product.md"};function p(l,t,c,u,h,g){const o=n("ImagePopup");return i(),a("div",null,[t[0]||(t[0]=e('<h1 id="bundle-product" tabindex="-1">Bundle Product <a class="header-anchor" href="#bundle-product" aria-label="Permalink to &quot;Bundle Product&quot;">​</a></h1><p>A bundle product is a kit that shoppers put together from options, such as an outfit where they choose the jeans, the jacket, the T-shirt and the shoes. Each option offers a few simple products, and the bundle&#39;s price is the total of the products the shopper chooses.</p><p>This page covers what&#39;s specific to bundle products. For the sections every product shares, see <a href="./products.html">Products</a>.</p><h2 id="create-a-bundle-product" tabindex="-1">Create a bundle product <a class="header-anchor" href="#create-a-bundle-product" aria-label="Permalink to &quot;Create a bundle product&quot;">​</a></h2><p>Create the product as described in <a href="./products.html#create-a-product">Create a product</a>, choosing <strong>Bundle</strong> as the <strong>Type</strong>.</p><p>A bundle product has no <strong>Price</strong>, <strong>Shipping</strong> or <strong>Inventories</strong> section. Prices, weights and stock come from the products in its options.</p><h2 id="add-an-option" tabindex="-1">Add an option <a class="header-anchor" href="#add-an-option" aria-label="Permalink to &quot;Add an option&quot;">​</a></h2><p>The <strong>Bundle Items</strong> section holds the bundle&#39;s options, such as <strong>Select Jeans</strong>.</p><ol><li>In <strong>Bundle Items</strong>, click <strong>Add Option</strong>. The <strong>Option</strong> dialog opens.</li><li>Enter the <strong>Title</strong> shoppers see for the option.</li><li>Choose the <strong>Type</strong>, which decides how shoppers choose: <ul><li><strong>Select</strong>: a drop-down list, one product.</li><li><strong>Radio</strong>: radio buttons, one product.</li><li><strong>Checkbox</strong>: tick boxes, any number of products.</li><li><strong>Multiselect</strong>: a list where shoppers can pick several products.</li></ul></li><li>Choose whether the option <strong>Is Required</strong>. When it&#39;s <strong>Yes</strong>, shoppers must choose from the option.</li><li>Click <strong>Save</strong>.</li></ol>',9)),s(o,{src:"/images/bundle-product/bundle-option.png",alt:"Option dialog with Title, Type and Is Required"}),t[1]||(t[1]=e('<p>To change an option, click <strong>Edit</strong> on it. <strong>Delete</strong> removes the option and its products.</p><h2 id="add-products-to-an-option" tabindex="-1">Add products to an option <a class="header-anchor" href="#add-products-to-an-option" aria-label="Permalink to &quot;Add products to an option&quot;">​</a></h2><ol><li>Click <strong>Add Product</strong> on the option. The <strong>Select Products</strong> panel opens.</li><li>Search for the products by name. Only simple products without customizable options are listed.</li><li>Tick the products.</li><li>Click <strong>Add Selected Product</strong>.</li><li>Enter the <strong>Default Qty</strong> for each product.</li><li>Mark the product chosen by default: the radio button for <strong>Select</strong> and <strong>Radio</strong> options, or the tick boxes for <strong>Checkbox</strong> and <strong>Multiselect</strong> options.</li><li>Click <strong>Save Product</strong>.</li></ol>',3)),s(o,{src:"/images/bundle-product/bundle-items.png",alt:"Bundle Items section with the Select Jeans option and its products"}),t[2]||(t[2]=e('<p>Drag a product by its handle to reorder it, or click <strong>Delete</strong> on its row to remove it.</p><h2 id="what-shoppers-see" tabindex="-1">What shoppers see <a class="header-anchor" href="#what-shoppers-see" aria-label="Permalink to &quot;What shoppers see&quot;">​</a></h2><p>The product page lists each option with its products and their prices, with the default products already chosen, and a <strong>Total Amount</strong> that updates as shoppers choose.</p><ul><li>For <strong>Select</strong> and <strong>Radio</strong> options, shoppers can change the quantity of the product they choose.</li><li>For <strong>Checkbox</strong> and <strong>Multiselect</strong> options, each product&#39;s <strong>Default Qty</strong> is used.</li><li>A <strong>Select</strong>, <strong>Radio</strong> or <strong>Multiselect</strong> option that isn&#39;t required also offers <strong>None</strong>.</li></ul>',4)),s(o,{src:"/images/bundle-product/output.png",alt:"Bundle product page with the Select Jeans and Select Jacket options"})])}const m=r(d,[["render",p]]);export{_ as __pageData,m as default};
